// สร้าง HTML ใบเสนอราคา ฟอนต์ Noto Sans Thai มีอยู่ใน container ของ Gotenberg
const q = $('อ่านใบเสนอราคา').item.json;
const fmt = n => Number(n).toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const d = DateTime.now().setZone('Asia/Bangkok');
const rows = q.lines.map((l, i) => `<tr><td>${i + 1}</td><td>${l.sku}</td><td>${l.name}</td><td class="n">${l.qty} ${l.unit}</td>
  <td class="n">${fmt(l.unit_price)}</td><td class="n">${l.discount_percent}%</td><td class="n">${fmt(l.net)}</td></tr>`).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><style>
body{font-family:'Noto Sans Thai',sans-serif;font-size:11pt;margin:24px}
h1{font-size:18pt;margin:0} table{width:100%;border-collapse:collapse;margin-top:16px}
th,td{border:1px solid #999;padding:4px 6px} th{background:#eee} .n{text-align:right}
</style></head><body>
<h1>ใบเสนอราคา</h1>
<p>บริษัท สยามพาร์ท ซัพพลาย จำกัด (ข้อมูลสมมุติเพื่อการฝึก)<br>เลขที่ ${q.quote_no} วันที่ ${d.day}/${d.month}/${d.year + 543} ยืนราคา 15 วัน</p>
<p>เรียน ${q.customer}</p>
<table><tr><th>ลำดับ</th><th>รหัส</th><th>รายการ</th><th>จำนวน</th><th>ราคาต่อหน่วย</th><th>ส่วนลด</th><th>จำนวนเงิน</th></tr>${rows}
<tr><td colspan="6" class="n">รวมก่อนภาษีมูลค่าเพิ่ม</td><td class="n">${fmt(q.net)}</td></tr>
<tr><td colspan="6" class="n">ภาษีมูลค่าเพิ่ม 7%</td><td class="n">${fmt(q.vat)}</td></tr>
<tr><td colspan="6" class="n"><b>รวมทั้งสิ้น</b></td><td class="n"><b>${fmt(q.total)}</b></td></tr></table>
<p>ยอดซื้อตั้งแต่ 3,000 บาทขึ้นไปส่งฟรี ราคานี้ยังไม่ใช่การยืนยันคำสั่งซื้อ</p></body></html>`;
return { json: { html, quote_no: q.quote_no } };

// Gotenberg คืนไฟล์ที่ชื่อเป็นรหัสสุ่ม ตั้งชื่อใหม่ตามเลขที่ใบเสนอราคาก่อนแนบอีเมล
$input.item.binary.data.fileName = $('สร้าง HTML').item.json.quote_no + '.pdf';
return $input.item;

